void SystemClock_Config(void)
{
  RCC_OscInitTypeDef osc = {0};
  RCC_ClkInitTypeDef clk = {0};

  /* 80MHz 属于 VOS1，先切电压档再动 PLL */
  __HAL_RCC_PWR_CLK_ENABLE();
  HAL_PWREx_ControlVoltageScaling(PWR_REGULATOR_VOLTAGE_SCALE1);
  while (__HAL_PWR_GET_FLAG(PWR_FLAG_VOS) == RESET) { }

  osc.OscillatorType = RCC_OSCILLATORTYPE_HSE;
  osc.HSEState       = RCC_HSE_ON;
  osc.PLL.PLLState   = RCC_PLL_ON;
  osc.PLL.PLLSource  = RCC_PLLSOURCE_HSE;
  osc.PLL.PLLM       = RCC_PLLM_DIV1;   /* 8MHz / 1 = 8MHz */
  osc.PLL.PLLN       = 20;              /* VCO = 8MHz x 20 = 160MHz */
  osc.PLL.PLLR       = RCC_PLLR_DIV2;   /* SYSCLK = 160MHz / 2 = 80MHz */
  if (HAL_RCC_OscConfig(&osc) != HAL_OK) { Error_Handler(); }

  clk.ClockType      = RCC_CLOCKTYPE_HCLK | RCC_CLOCKTYPE_SYSCLK |
                       RCC_CLOCKTYPE_PCLK1 | RCC_CLOCKTYPE_PCLK2;
  clk.SYSCLKSource   = RCC_SYSCLKSOURCE_PLLCLK;
  clk.AHBCLKDivider  = RCC_SYSCLK_DIV1;    /* HCLK = 80MHz */
  clk.APB1CLKDivider = RCC_HCLK_DIV1;      /* PCLK1，L4 的 APB1 也能到 80MHz */
  clk.APB2CLKDivider = RCC_HCLK_DIV1;      /* PCLK2 */
  /* 80MHz/VOS1 要 4 个 Flash 等待周期，具体查数据手册 latency 表 */
  if (HAL_RCC_ClockConfig(&clk, FLASH_LATENCY_4) != HAL_OK) { Error_Handler(); }
  SystemCoreClockUpdate();
}

