I2C_HandleTypeDef hi2c1;       /* CubeMX 生成 */
#define MPU_ADDR 0x68          /* 7 位地址 */

static uint8_t ReadReg(uint8_t dev, uint8_t reg)
{
  uint8_t v = 0;
  HAL_I2C_Mem_Read(&hi2c1, dev << 1, reg, I2C_MEMADD_SIZE_8BIT, &v, 1, 100);
  return v;
}

static void WriteReg(uint8_t dev, uint8_t reg, uint8_t v)
{
  HAL_I2C_Mem_Write(&hi2c1, dev << 1, reg, I2C_MEMADD_SIZE_8BIT, &v, 1, 100);
}

int main(void)
{
  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  MX_I2C1_Init();

  /* USER CODE BEGIN 2 */
  for (uint8_t a = 1; a < 127; a++) {           /* 总线扫描 */
    if (HAL_I2C_IsDeviceReady(&hi2c1, a << 1, 3, 10) == HAL_OK) {
      /* 记录或打印地址 a */
    }
  }
  uint8_t who = ReadReg(MPU_ADDR, 0x75);        /* WHO_AM_I */
  WriteReg(MPU_ADDR, 0x6B, 0x00);               /* 唤醒 MPU6050 */
  /* USER CODE END 2 */

  uint8_t accel[6];
  while (1) {
    /* USER CODE BEGIN 3 */
    HAL_I2C_Mem_Read(&hi2c1, MPU_ADDR << 1, 0x3B,
                     I2C_MEMADD_SIZE_8BIT, accel, 6, 100);
    HAL_Delay(50);
    /* USER CODE END 3 */
  }
}

