/* 参数区地址按所选型号的页/扇区划分与链接脚本确定，不要照抄别的工程 */
#define PARAM_ADDR   0x08060000UL
#define PARAM_VALUE  0x12345678UL

static uint32_t Flash_WriteParam(uint32_t addr, uint32_t value)
{
  FLASH_EraseInitTypeDef erase = {0};
  uint32_t err = 0;

  HAL_FLASH_Unlock();
  __HAL_FLASH_CLEAR_FLAG(FLASH_FLAG_EOP);   /* 其余错误标志按系列补 */

  /* 擦除粒度随系列不同：按页用 Page/NbPages（字段名可能是 Page 或 PageAddress，有的还要 Banks），
     按扇区用 Sector/NbSectors/VoltageRange，字段以 HAL 头文件为准 */
  erase.TypeErase = FLASH_TYPEERASE_PAGES;
  erase.Page = 0;          /* 字段名随系列不同，换成参数区所在页号 */
  erase.NbPages = 1;
  if (HAL_FLASHEx_Erase(&erase, &err) != HAL_OK) {
    HAL_FLASH_Lock();
    return 1;
  }
  /* 编程粒度随系列不同（半字/字/双字/四字），类型宏以 HAL 头文件为准 */
  if (HAL_FLASH_Program(FLASH_TYPEPROGRAM_WORD, addr, value) != HAL_OK) {
    HAL_FLASH_Lock();
    return 2;
  }
  HAL_FLASH_Lock();
  return 0;                       /* 之后回读 *(uint32_t *)addr 校验 */
}

