                       | FLASH_FLAG_WRPERR | FLASH_FLAG_PGAERR
                       | FLASH_FLAG_SIZERR | FLASH_FLAG_PGSERR);

  if (HAL_FLASH_Program(FLASH_TYPEPROGRAM_DOUBLEWORD, PARAM_ADDR, value) != HAL_OK) {
    HAL_FLASH_Lock();
    return -1;
  }

  HAL_FLASH_Lock();
  return 0;
}

