  er.Banks      = FLASH_BANK_1;   /* 双 Bank 器件按目标 Bank 选 */
  er.Sector     = 1U;             /* 扇区号按型号扇区表 */
  er.NbSectors  = 1U;
  er.VoltageRange = FLASH_VOLTAGE_RANGE_3;

  if (HAL_FLASHEx_Erase(&er, &sector_err) != HAL_OK)
  {
    Error_Handler();
  }
  HAL_FLASH_Lock();
}

