sFilterConfig.FilterIndex  = 0;
sFilterConfig.FilterType   = FDCAN_FILTER_MASK;
sFilterConfig.FilterConfig = FDCAN_FILTER_TO_RXFIFO0;
sFilterConfig.FilterID1    = 0x123;
sFilterConfig.FilterID2    = 0x7FF;
if (HAL_FDCAN_ConfigFilter(&hfdcan1, &sFilterConfig) != HAL_OK)
{
  Error_Handler();
}

/* 2) 未匹配帧丢弃 */
HAL_FDCAN_ConfigGlobalFilter(&hfdcan1, FDCAN_REJECT, FDCAN_REJECT,
                             FDCAN_REJECT_REMOTE, FDCAN_REJECT_REMOTE);

/* 3) 使能 Rx FIFO0 新报文中断后再启动 */
HAL_FDCAN_ActivateNotification(&hfdcan1, FDCAN_IT_RX_FIFO0_NEW_MESSAGE, 0);

if (HAL_FDCAN_Start(&hfdcan1) != HAL_OK)
{
  Error_Handler();
}

/* 改位时序：先停机 */
if (HAL_FDCAN_Stop(&hfdcan1) != HAL_OK)
{
  Error_Handler();
}

/* 42 MHz / (12 x (1 + 11 + 2)) = 250 kbps */
hfdcan1.Init.NominalPrescaler = 12;
hfdcan1.Init.NominalTimeSeg1  = 11;
hfdcan1.Init.NominalTimeSeg2  = 2;
if (HAL_FDCAN_Init(&hfdcan1) != HAL_OK)
{
  Error_Handler();
}

/* 重新配置过滤器后再启动（Init 会重算消息 RAM 布局） */
HAL_FDCAN_ConfigFilter(&hfdcan1, &sFilterConfig);

if (HAL_FDCAN_Start(&hfdcan1) != HAL_OK)
{
  Error_Handler();
}

FDCAN_FilterTypeDef sFilterConfig;

/* 只接收标准 ID 0x123，命中送 FIFO0 */
sFilterConfig.IdType       = FDCAN_STANDARD_ID;
sFilterConfig.FilterIndex  = 0;
sFilterConfig.FilterType   = FDCAN_FILTER_MASK;
sFilterConfig.FilterConfig = FDCAN_FILTER_TO_RXFIFO0;
sFilterConfig.FilterID1    = 0x123;
sFilterConfig.FilterID2    = 0x7FF;          /* 11 位全比较 */
if (HAL_FDCAN_ConfigFilter(&hfdcan1, &sFilterConfig) != HAL_OK)
{
  Error_Handler();
}

/* 扩展 ID 0x18FF0000 ~ 0x18FFFFFF 命中送 FIFO1 */
sFilterConfig.IdType       = FDCAN_EXTENDED_ID;
sFilterConfig.FilterIndex  = 0;
sFilterConfig.FilterConfig = FDCAN_FILTER_TO_RXFIFO1;
sFilterConfig.FilterID1    = 0x18FF0000;
sFilterConfig.FilterID2    = 0x1FFF0000;     /* 只比较高 13 位 */
HAL_FDCAN_ConfigFilter(&hfdcan1, &sFilterConfig);

/* 生产配置：未匹配帧丢弃，远程帧也拒收 */
if (HAL_FDCAN_ConfigGlobalFilter(&hfdcan1,
                                 FDCAN_REJECT,          /* NonMatchingStd */
                                 FDCAN_REJECT,          /* NonMatchingExt */
                                 FDCAN_REJECT_REMOTE,   /* RejectRemoteStd */
                                 FDCAN_REJECT_REMOTE)   /* RejectRemoteExt */
    != HAL_OK)
{
  Error_Handler();
}

/* 调试配置：先收全总线，看清有哪些 ID 再收紧过滤 */
HAL_FDCAN_ConfigGlobalFilter(&hfdcan1,
                             FDCAN_ACCEPT_IN_RX_FIFO0,
                             FDCAN_ACCEPT_IN_RX_FIFO0,
                             FDCAN_FILTER_REMOTE,
                             FDCAN_FILTER_REMOTE);

/* Rx FIFO0 有新报文 → 回调里取帧 */
HAL_FDCAN_ActivateNotification(&hfdcan1, FDCAN_IT_RX_FIFO0_NEW_MESSAGE, 0);

/* Tx 完成：只关心 Tx Buffer 0 */
HAL_FDCAN_ActivateNotification(&hfdcan1, FDCAN_IT_TX_COMPLETE, FDCAN_TX_BUFFER0);

/* Bus-Off 与错误状态变化 */
HAL_FDCAN_ActivateNotification(&hfdcan1, FDCAN_IT_BUS_OFF | FDCAN_IT_ERROR_PASSIVE, 0);

/* stm32xx_it.c：中断入口统一转给 HAL */
void FDCAN1_IT0_IRQHandler(void)
{
  HAL_FDCAN_IRQHandler(&hfdcan1);
}

/* 回调：一次取一帧 */
void HAL_FDCAN_RxFifo0Callback(FDCAN_HandleTypeDef *hfdcan, uint32_t RxFifo0ITs)
{
  FDCAN_RxHeaderTypeDef rxHeader;
  uint8_t rxData[64];

  if ((RxFifo0ITs & FDCAN_IT_RX_FIFO0_NEW_MESSAGE) != 0U)
  {
    HAL_FDCAN_GetRxMessage(hfdcan, FDCAN_RX_FIFO0, &rxHeader, rxData);
  }
}

FDCAN_RxHeaderTypeDef rxHeader;
uint8_t rxData[64];

/* 从 FIFO0 取一帧 */
if (HAL_FDCAN_GetRxMessage(&hfdcan1, FDCAN_RX_FIFO0, &rxHeader, rxData) == HAL_OK)
{
  /* 标准帧还是扩展帧由 IdType 区分 */
  if (rxHeader.IdType == FDCAN_STANDARD_ID)
  {
    /* rxHeader.Identifier 为 11 位标准 ID */
  }
  else
  {
    /* rxHeader.Identifier 为 29 位扩展 ID */
  }

  /* DataLength 是 DLC 编码：0~8 = 字节数，9~15 = 12~64 字节 */
  if (rxHeader.FDFormat == FDCAN_FD_CAN)
  {
    /* FD 帧，数据最多 64 字节 */
  }

  /* 命中的过滤器索引，便于区分报文来源 */
  uint32_t filterIndex = rxHeader.FilterIndex;
  (void)filterIndex;
}

FDCAN_TxHeaderTypeDef txHeader;
uint8_t txData[8] = {0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88};

txHeader.Identifier          = 0x123;
txHeader.IdType              = FDCAN_STANDARD_ID;
txHeader.TxFrameType         = FDCAN_DATA_FRAME;
txHeader.DataLength          = FDCAN_DLC_BYTES_8;
txHeader.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
txHeader.BitRateSwitch       = FDCAN_BRS_OFF;
txHeader.FDFormat            = FDCAN_CLASSIC_CAN;
txHeader.TxEventFifoControl  = FDCAN_STORE_TX_EVENTS;
txHeader.MessageMarker       = 0x01;

if (HAL_FDCAN_GetTxFifoFreeLevel(&hfdcan1) > 0U)
{
  if (HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &txHeader, txData) != HAL_OK)
  {
    Error_Handler();
  }
}

FDCAN_TxHeaderTypeDef txHeader;
FDCAN_TxEventFifoTypeDef txEvent;
uint32_t txTimestamp;
uint8_t txMarker;
uint8_t txData[8] = {0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88};

/* 发送时打开事件记录，发送结果与时间戳才会进 Tx 事件 FIFO */
txHeader.Identifier          = 0x123;
txHeader.IdType              = FDCAN_STANDARD_ID;
txHeader.TxFrameType         = FDCAN_DATA_FRAME;
txHeader.DataLength          = FDCAN_DLC_BYTES_8;
txHeader.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
txHeader.BitRateSwitch       = FDCAN_BRS_OFF;
txHeader.FDFormat            = FDCAN_CLASSIC_CAN;
txHeader.TxEventFifoControl  = FDCAN_STORE_TX_EVENTS;
txHeader.MessageMarker       = 0x01;

if (HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &txHeader, txData) != HAL_OK)
{
  Error_Handler();
}

/* 主循环里轮询：读出事件即可拿到发送时间戳与 MessageMarker */
while (HAL_FDCAN_GetTxEvent(&hfdcan1, &txEvent) == HAL_OK)
{
  txTimestamp = txEvent.TxTimestamp;   /* 16 位，需已使能时间戳计数器 */
  txMarker    = txEvent.MessageMarker;
}

/* IT0：收帧与总线错误 */
HAL_FDCAN_ConfigInterruptLines(&hfdcan1,
                               FDCAN_IT_RX_FIFO0_NEW_MESSAGE |
                               FDCAN_IT_RX_FIFO1_NEW_MESSAGE |
                               FDCAN_IT_BUS_OFF,
                               FDCAN_INTERRUPT_LINE0);

/* IT1：发送完成 */
HAL_FDCAN_ConfigInterruptLines(&hfdcan1,
                               FDCAN_IT_TX_COMPLETE,
                               FDCAN_INTERRUPT_LINE1);

/* 再打开具体中断源 */
HAL_FDCAN_ActivateNotification(&hfdcan1, FDCAN_IT_RX_FIFO0_NEW_MESSAGE, 0);
HAL_FDCAN_ActivateNotification(&hfdcan1, FDCAN_IT_TX_COMPLETE, FDCAN_TX_BUFFER0);

/* NVIC 侧两条线都要使能 */
HAL_NVIC_EnableIRQ(FDCAN1_IT0_IRQn);
HAL_NVIC_EnableIRQ(FDCAN1_IT1_IRQn);

uint32_t fillLevel = HAL_FDCAN_GetRxFifoFillLevel(&hfdcan1, FDCAN_RX_FIFO0);
FDCAN_RxHeaderTypeDef rxHeader;
uint8_t rxData[64];

/* 把 FIFO0 里现有的帧一次取空 */
while (fillLevel > 0U)
{
  if (HAL_FDCAN_GetRxMessage(&hfdcan1, FDCAN_RX_FIFO0, &rxHeader, rxData) == HAL_OK)
  {
    /* DataLength 为 DLC 编码：0~8 = 字节数，9~15 = 12~64 字节 */
    ProcessFrame(rxHeader.Identifier, rxHeader.IdType, rxData, rxHeader.DataLength);
  }

  fillLevel = HAL_FDCAN_GetRxFifoFillLevel(&hfdcan1, FDCAN_RX_FIFO0);
}

/* 1) 先按 FD + BRS 初始化：数据段 2 Mbps（假设 FDCAN 时钟 80 MHz） */
hfdcan1.Init.FrameFormat   = FDCAN_FRAME_FD_BRS;
hfdcan1.Init.DataPrescaler = 1;
hfdcan1.Init.DataTimeSeg1  = 5;
hfdcan1.Init.DataTimeSeg2  = 2;
HAL_FDCAN_Init(&hfdcan1);

/* 2) 初始化态写 TDC：80 MHz / 1 = 12.5 ns/tq */
/*    收发器环路延迟约 100 ns，TdcOffset = 100 / 12.5 = 8 */
if (HAL_FDCAN_ConfigTxDelayCompensation(&hfdcan1, 8U, 8U) != HAL_OK)
{
  Error_Handler();
}

/* 3) 启动后 FD 数据段即带延迟补偿 */
if (HAL_FDCAN_Start(&hfdcan1) != HAL_OK)
{
  Error_Handler();
}
